        entity: text("entity").notNull(),
        // 'workflow' | 'node' | 'edge' | 'trigger' | 'schedule'
        entityId: text("entity_id"),
        action: text("action").notNull(),
        // 'create' | 'delete' | 'rename' | 'config' | 'update'
        details: jsonb("details").notNull().default(sql`'{}'::jsonb`),
