function categoryToGroup(category) {
  switch (category) {
    case "trigger":
    case "control":
      return "Trigger & Flow";
    case "agentic":
      return "LLM & AI";
    case "integration":
      return "Integrations";
    case "core":
      return "Parse & Transform";
    default:
      return "Integrations";
  }
}
